-- ===========================================================================
-- 主数据（MDM）四块菜单：物料 / 工程 / 销售 / 生产
--
-- 用途：把这四块已并入主平台的菜单、按钮与内置角色授权补进**已存在**的项目
--       （当前绑定项目 xmgl 等）；全新的空项目直接执行 platform-seed.sql 即可，
--       其中已包含这些行（生成器 scripts/build-platform-baseline.ts 会把它们的
--       app_code 从 mdm 改写为 platform）。
--
-- 来源：旧项目 MDM 应用的四组菜单子树（复用原 id 与权限码 Mdm*），
--       页面位于 src/views/mdm/**，component 路径保持 /mdm/... 由平台视图加载器解析。
--
-- 幂等：菜单按主键 id 去重并更新描述字段；授权按 (role_id, menu_id) 唯一键去重。
-- 授权：平台内置角色 R_SUPER（超级管理员）与 R_ADMIN（管理员）。
--       其他角色请执行后到「系统管理 / 角色管理」按需分配。
--
-- 应用方式：在目标项目执行整段 SQL（Supabase SQL 编辑器、supabase db query 或
--           MCP execute_sql 均可）。
-- ===========================================================================

begin;

-- 1) 菜单、文件夹与按钮
on conflict ("id") do update set
  "name" = excluded."name",
  "path" = excluded."path",
  "component" = excluded."component",
  "meta" = excluded."meta",
  "sort" = excluded."sort",
  "parent_id" = excluded."parent_id",
  "type" = excluded."type",
  "app_code" = excluded."app_code",
  "update_by" = excluded."update_by",
  "update_time" = excluded."update_time";

-- 2) 授予内置角色（R_SUPER / R_ADMIN），授权范围＝上面整棵子树
select role_row."id", menu_row."id", role_row."tenant_id", 'setup-sql', 'setup-sql'
from public.sys_role role_row
join public.sys_menu menu_row on menu_row."id" in (
